+++ b/training/level-2/L2-007-bookmark-store/bookmarkStore.mjs
@@ -0,0 +1,163 @@
+// This is a synchronous bookmark store implementation
+
+import { promises as fs } from 'fs';
+import { dirname, resolve } from 'path';
+import { randomUUID } from 'crypto';
+
+const STATE_CORRUPT = 'STATE_CORRUPT';
+const INVALID_BOOKMARK = 'INVALID_BOOKMARK';
+const DUPLICATE_ID = 'DUPLICATE_ID';
+const INVALID_PATCH = 'INVALID_PATCH';
+const NOT_FOUND = 'NOT_FOUND';
+
+function normalizeUrl(url) {
+  try {
+    const urlObj = new URL(url);
+    return urlObj.toString();
+  } catch (e) {
+    return url;
+  }
+}
+
+function createBookmarkStore(filePath) {
+  return {
+    async add(bookmark) {
+      const { id, title, url, tags } = bookmark;
+
+      // Validate fields
+      if (!id || !title || !url || !tags) {
+        throw new Error(INVALID_BOOKMARK);
+      }
+
+      // Normalize URL
+      const normalizedUrl = normalizeUrl(url);
+      if (!normalizedUrl.startsWith('http://') && !normalizedUrl.startsWith('https://')) {
+        throw new Error(INVALID_BOOKMARK);
+      }
+
+      // Check for duplicate ID
+      const bookmarks = await this.getAll();
+      const existingBookmark = bookmarks.find(b => b.id === id);
+      if (existingBookmark) {
+        throw new Error(DUPLICATE_ID);
+      }
+
+      // Validate tags
+      if (!Array.isArray(tags) || tags.some(tag => typeof tag !== 'string')) {
+        throw new Error(INVALID_BOOKMARK);
+      }
+
+      // Create new bookmark
+      const newBookmark = {
+        id,
+        title: title.trim(),
+        url: normalizedUrl,
+        tags: tags.map(tag => tag.trim()),
+      };
+
+      // Write to file
+      await fs.writeFile(filePath, JSON.stringify([...bookmarks, newBookmark], null, 2));
+
+      return newBookmark;
+    },
+
+    async getAll() {
+      try {
+        const data = await fs.readFile(filePath, 'utf-8');
+        const bookmarks = JSON.parse(data);
+
+        // Validate all bookmarks
+        for (const bookmark of bookmarks) {
+          if (!bookmark.id || !bookmark.title || !bookmark.url || !bookmark.tags) {
+            throw new Error(STATE_CORRUPT);
+          }
+
+          // Check for duplicate IDs
+          const duplicate = bookmarks.find(b => b.id === bookmark.id && b !== bookmark);
+          if (duplicate) {
+            throw new Error(STATE_CORRUPT);
+          }
+
+          // Validate tags
+          if (!Array.isArray(bookmark.tags) || bookmark.tags.some(tag => typeof tag !== 'string')) {
+            throw new Error(STATE_CORRUPT);
+          }
+        }
+
+        return bookmarks;
+      } catch (e) {
+        if (e.code === 'ENOENT') {
+          return [];
+        } else {
+          throw new Error(STATE_CORRUPT);
+        }
+      }
+    },
+
+    async get(id) {
+      const bookmarks = await this.getAll();
+      const bookmark = bookmarks.find(b => b.id === id);
+      if (!bookmark) {
+        throw new Error(NOT_FOUND);
+      }
+      return bookmark;
+    },
+
+    async update(id, patch) {
+      const bookmarks = await this.getAll();
+      const bookmark = bookmarks.find(b => b.id === id);
+      if (!bookmark) {
+        throw new Error(NOT_FOUND);
+      }
+
+      // Validate patch
+      if (Object.keys(patch).length === 0) {
+        throw new Error(INVALID_PATCH);
+      }
+
+      // Apply patch
+      const updatedBookmark = {
+        ...bookmark,
+        ...patch,
+      };
+
+      // Validate updated bookmark
+      if (!updatedBookmark.id || !updatedBookmark.title || !updatedBookmark.url || !updatedBookmark.tags) {
+        throw new Error(STATE_CORRUPT);
+      }
+
+      // Normalize URL
+      const normalizedUrl = normalizeUrl(updatedBookmark.url);
+      if (!normalizedUrl.startsWith('http://') && !normalizedUrl.startsWith('https://')) {
+        throw new Error(STATE_CORRUPT);
+      }
+
+      // Validate tags
+      if (!Array.isArray(updatedBookmark.tags) || updatedBookmark.tags.some(tag => typeof tag !== 'string')) {
+        throw new Error(STATE_CORRUPT);
+      }
+
+      // Write to file
+      await fs.writeFile(filePath, JSON.stringify([...bookmarks.filter(b => b.id !== id), updatedBookmark], null, 2));
+
+      return updatedBookmark;
+    },
+
+    async remove(id) {
+      const bookmarks = await this.getAll();
+      const bookmark = bookmarks.find(b => b.id === id);
+      if (!bookmark) {
+        throw new Error(NOT_FOUND);
+      }
+
+      // Write to file
+      await fs.writeFile(filePath, JSON.stringify([...bookmarks.filter(b => b.id !== id)], null, 2));
+
+      return bookmark;
+    },
+
+    // Additional methods can be added here
+  };
+}
+
+export { createBookmarkStore };

